 for (const line of fs.readFileSync('/tmp/threads/'+f,'utf8').split('\n')) { if(!line.trim()) continue; const b=JSON.parse(line);
  for (const w of b.writes) { if (w.type==='task'||w.type==='document.change'||w.type==='document.create'||w.type==='submission') { const k=w.type+':'+(w.value?.kind||w.value?.type||w.kind||''); kinds[k]=(kinds[k]||0)+1; if(!seen[k]){seen[k]=JSON.stringify(w).slice(0,700);} }
